<?php $pageTitle='Shift Management';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager','cashier','operator']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();if($_POST['action']==='open'){if(activeShiftId()){$flash='A shift is already open.';$error=true;}else{$cash=max(0,(float)$_POST['opening_cash']);$db->prepare("INSERT INTO shifts(club_id,operator_id,start_time,opening_cash,status) VALUES(?,?,NOW(),?,'open')")->execute([$club,$_SESSION['user_id'],$cash]);$flash='Shift opened.';}}elseif($_POST['action']==='close'&&($id=activeShiftId())){$shift=$db->prepare('SELECT * FROM shifts WHERE id=?');$shift->execute([$id]);$shift=$shift->fetch();$cash=max(0,(float)$_POST['closing_cash']);$expected=$shift['opening_cash']+$shift['total_revenue'];$db->prepare("UPDATE shifts SET status='closed',end_time=NOW(),closing_cash=?,expected_cash=?,cash_discrepancy=?,notes=? WHERE id=?")->execute([$cash,$expected,$cash-$expected,sanitize($_POST['notes']??''),$id]);$flash='Shift closed and reconciled.';}}$activeId=activeShiftId();$active=null;if($activeId){$q=$db->prepare('SELECT s.*,u.name operator_name FROM shifts s JOIN users u ON u.id=s.operator_id WHERE s.id=?');$q->execute([$activeId]);$active=$q->fetch();}$q=$db->prepare('SELECT s.*,u.name operator_name FROM shifts s JOIN users u ON u.id=s.operator_id WHERE s.club_id=? ORDER BY s.start_time DESC LIMIT 30');$q->execute([$club]);$rows=$q->fetchAll();?><h1 class="text-2xl font-bold">Shift Management</h1><?php if(isset($flash)):?><p class="mt-4 <?=$error??false?'text-red-300':'text-green-300'?>"><?=sanitize($flash)?></p><?php endif?><section class="card mt-5"><?php if($active):?><p class="text-xs uppercase text-green-400">Open Shift</p><h2 class="text-xl font-bold mt-1">Opened by <?=sanitize($active['operator_name'])?> at <?=date('h:i A',strtotime($active['start_time']))?></h2><div class="grid grid-cols-3 gap-4 mt-5"><div><p class="text-slate-400 text-xs">Opening Cash</p><b><?=money($active['opening_cash'])?></b></div><div><p class="text-slate-400 text-xs">Revenue</p><b><?=money($active['total_revenue'])?></b></div><div><p class="text-slate-400 text-xs">Transactions</p><b><?=$active['total_transactions']?></b></div></div><form method="post" class="mt-5 grid md:grid-cols-3 gap-3"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="action" value="close"><input class="input" type="number" name="closing_cash" min="0" step=".01" required placeholder="Closing cash"><input class="input" name="notes" placeholder="Required if discrepancy is high"><button class="btn-danger">Close Shift</button></form><?php else:?><h2 class="text-xl font-bold">No Active Shift</h2><form method="post" class="flex gap-3 mt-4"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="action" value="open"><input class="input max-w-xs" type="number" min="0" step=".01" name="opening_cash" placeholder="Opening cash" required><button class="btn-primary">Open Shift</button></form><?php endif?></section><section class="card mt-5 overflow-x-auto"><h2 class="font-bold mb-3">Shift History</h2><table class="data-table w-full"><thead><tr><th>Date</th><th>Operator</th><th>Open</th><th>Close</th><th>Revenue</th><th>Opening</th><th>Closing</th><th>Discrepancy</th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><?=date('d M Y',strtotime($s['start_time']))?></td><td><?=sanitize($s['operator_name'])?></td><td><?=date('H:i',strtotime($s['start_time']))?></td><td><?=$s['end_time']?date('H:i',strtotime($s['end_time'])):'Open'?></td><td><?=money($s['total_revenue'])?></td><td><?=money($s['opening_cash'])?></td><td><?=money($s['closing_cash'])?></td><td class="<?=abs($s['cash_discrepancy'])>100?'text-red-300':''?>"><?=money($s['cash_discrepancy'])?></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
